Here's how to write modern MSTest tests for your `DataFetcher` class:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_SuccessfulResponse_ReturnsContent()
    {
        // Arrange
        var handler = new MockHttpMessageHandler("hello world", HttpStatusCode.OK);
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        // Act
        var result = await fetcher.FetchAsync("https://example.com", _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_NotFound_ThrowsHttpRequestException()
    {
        // Arrange
        var handler = new MockHttpMessageHandler("", HttpStatusCode.NotFound);
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        // Act & Assert
        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await fetcher.FetchAsync("https://example.com/missing", _testContext.CancellationToken));
    }

    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_CancellationRequested_ThrowsTaskCanceledException()
    {
        // Arrange
        var handler = new MockHttpMessageHandler("data", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(10));
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // Cancel immediately

        // Act & Assert
        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_RespectsTimeoutViaCancellationToken()
    {
        // Arrange
        var handler = new MockHttpMessageHandler("slow", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(30));
        var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        // Use TestContext.CancellationToken — will fire when [Timeout] expires
        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await fetcher.FetchAsync("https://example.com/slow", _testContext.CancellationToken));
    }

    // Reusable fake handler
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        private readonly string _content;
        private readonly HttpStatusCode _statusCode;
        private readonly TimeSpan _delay;

        public MockHttpMessageHandler(string content, HttpStatusCode statusCode, TimeSpan delay = default)
        {
            _content = content;
            _statusCode = statusCode;
            _delay = delay;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (_delay > TimeSpan.Zero)
                await Task.Delay(_delay, cancellationToken);

            return new HttpResponseMessage(_statusCode)
            {
                Content = new StringContent(_content)
            };
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---------|-----|
| **Async tests** | `async Task` return type — MSTest awaits them natively |
| **Timeouts** | `[Timeout(ms)]` — fires `TestContext.CancellationToken` on expiry |
| **CancellationToken forwarding** | Pass `_testContext.CancellationToken` so the test respects `[Timeout]` |
| **Testing cancellation** | Create a pre-cancelled `CancellationTokenSource` and assert `TaskCanceledException` |
| **Exception assertions** | `Assert.ThrowsExactlyAsync<T>` instead of `[ExpectedException]` |
| **Sealed class** | Performance best practice for test classes |
| **Constructor-injected TestContext** | MSTest 3.6+ pattern for accessing `CancellationToken` |

The critical insight: always pass `_testContext.CancellationToken` (or your own `CancellationTokenSource.Token`) into async methods under test — this connects MSTest's `[Timeout]` mechanism to your code, ensuring tests fail fast rather than hanging indefinitely.
